; Size of the next enemy wave
; $4a80-$4aba

; Sets the enemy count of a wave $66 from the score digits $13 and $14: 2 below 400, 3 from 400, 4 from 1500. Then sets $62 = 2 * $66 + 2 plus $66 - 1 random values 0-3.
set_wave_size
        lda #$02
        sta wave_size
        lda score+1                     ; Score thousands digit. The ten-thousands digit $12 is not tested.
        cmp #$01
        beq wave_size_check_1000s
        bcs wave_size_four
        bcc wave_size_check_below_1000
wave_size_check_1000s
        lda score+2                     ; Score 1000-1499: 3, from 1500: 4.
        cmp #$05
        bcc wave_size_three
wave_size_four
        lda #$04
        bne wave_size_store
wave_size_check_below_1000
        lda score+2                     ; Score below 1000: 2 below 400, else 3.
        cmp #$04
        bcc wave_size_set_interval
wave_size_three
; not executed $4a9e-$4a9f
        lda #$03
wave_size_store
        sta wave_size
wave_size_set_interval
        lda wave_size
        asl
        clc
        adc #$02
        sta launch_delay
        ldy wave_size
        dey
wave_size_add_random
        lda RANDOM                      ; SID voice 3 oscillator output as a random value.
        and #$03
        clc
        adc launch_delay
        sta launch_delay
